SELECT DATE_TRUNC('DAY', reading_ts) AS activity_day, COUNT(*) FILTER (WHERE device_code = 'DV-02') AS dv_02_rows, STDDEV_SAMP(temp_c) AS temp_c_stddev, STDDEV_SAMP(status_bits) AS status_bits_stddev, COUNT(*) FILTER (WHERE device_code = 'DV-03') AS dv_03_rows, COUNT_IF(device_code = 'DV-03') AS dv_03_events, AVG(pressure) FILTER (WHERE device_code = 'DV-01') AS dv_01_avg_pressure FROM device_readings GROUP BY activity_day ORDER BY dv_03_rows NULLS FIRST
